"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import { PauseIcon, PlayIcon } from "@hugeicons/core-free-icons";
import { planeFrom } from "@/components/anatomy/axis-parts";
import { IsoFigure, Line, Solid } from "@/components/anatomy/react/draw";
import { asksForStillness, follow, useInView, useStillness } from "@/components/anatomy/react/live";
import { translateAlong } from "@/components/anatomy/iso-kit";
import { LiveSolid, type SolidHandle } from "@/components/anatomy/live-solid";
import {
  BASE_LINES,
  BASE_PARTS,
  BEAM_LINES,
  BEATER_STYLE,
  BED_Z,
  CLOTH_BEAM_LINES,
  CLOTH_BEAM_PARTS,
  CLOTH_LEN,
  FELL_Y,
  FRAME_LINES,
  FRAME_PARTS,
  HALO,
  HEIGHT,
  HEDDLE_LINES,
  HEDDLE_PARTS,
  P,
  POINTER,
  POINTER_LINE,
  ROWS,
  RULE_LINES,
  SHUTTLE_PARTS,
  SHUTTLE_SIT,
  SLOT_WARP,
  WARP_BEAM_PARTS,
  WEAVE_ALL,
  WIDTH,
  beaterLines,
  beaterParts,
  clockFor,
  clothClip,
  clothRoll,
  clothShape,
  holeWarp,
  loomPose,
  pointerSlide,
  stateText,
  tourAt,
  type Ink,
  type LoomPose,
  type Part,
} from "./loom";
import "./the-loom.css";

const MOST_DT = 1 / 30;
const SEEK = 0.12; // seconds for the loom to answer a reader's hand
const CLIP = "the-loom-cloth";
/** the frame the drawing is about: a cloth half along, the shed open and the
    shuttle mid-flight, so all four readings of the number are on show at once */
const SHOWN = 0.62;
const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x);

/* the loom is handed over mid-cloth, so the tour's first act is to weave the
   rows still to come rather than to wind the cloth back off the beam */
const STILL: LoomPose = loomPose(SHOWN);
const BEATER_STILL = beaterParts(STILL.phi);
const COMB_STILL = beaterLines(STILL.phi);

/**
 * A still frame to check the drawing by: `?at=0` holds the bare fell, `?at=1`
 * holds the finished cloth, anything between scrubs to there. Development only.
 */
function fixedFromQuery(): number | null {
  if (!import.meta.env.DEV || typeof window === "undefined") return null;
  const raw = new URLSearchParams(window.location.search).get("at");
  if (raw === null) return null;
  const value = Number(raw);
  return Number.isFinite(value) ? clamp01(value) : null;
}

function solids(list: Part[], tag: string) {
  return list.map((item, index) => <Solid key={`${tag}${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} className={item.mark} />);
}
function inks(list: Ink[], tag: string) {
  return list.map((item, index) => <Line key={`${tag}${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />);
}

export interface TheLoomProps {
  /** Dark or light drawing. The figure carries its own theme scope. */
  theme?: "dark" | "light";
  className?: string;
  /** Controlled play state. Leave undefined to let the figure own it. */
  playing?: boolean;
  /** Where an uncontrolled figure starts. Defaults to playing. */
  defaultPlaying?: boolean;
  onPlayingChange?: (playing: boolean) => void;
}

export function TheLoom({ theme = "dark", className, playing: controlled, defaultPlaying = true, onPlayingChange }: TheLoomProps) {
  const fixed = React.useMemo(fixedFromQuery, []);
  const fixedRef = React.useRef(fixed);
  fixedRef.current = fixed;

  const [own, setOwn] = React.useState(defaultPlaying);
  const playing = fixed === null ? (controlled ?? own) : false;
  const setPlaying = React.useCallback(
    (next: boolean) => {
      if (controlled === undefined) setOwn(next);
      onPlayingChange?.(next);
    },
    [controlled, onPlayingChange],
  );

  const root = React.useRef<HTMLDivElement | null>(null);
  const inView = useInView(root);

  const heddle = React.useRef<SVGGElement | null>(null);
  const shuttle = React.useRef<SVGGElement | null>(null);
  const pointer = React.useRef<SVGGElement | null>(null);
  const cloth = React.useRef<SolidHandle | null>(null);
  const roll = React.useRef<SolidHandle | null>(null);
  const clip = React.useRef<SVGPathElement | null>(null);
  const hole = React.useRef<SVGPathElement | null>(null);
  const weft = React.useRef<SVGPathElement | null>(null);
  const comb = React.useRef<SVGPathElement | null>(null);
  const beater = React.useMemo(() => BEATER_STYLE.map(() => React.createRef<SolidHandle>()), []);

  const state = React.useRef({ at: fixed ?? SHOWN, want: fixed ?? SHOWN, clock: clockFor(fixed ?? SHOWN) });
  const playRef = React.useRef(playing);
  const frame = React.useRef(0);
  const last = React.useRef(0);
  const [pressing, setPressing] = React.useState(false);
  const grab = React.useRef(0);

  const draw = React.useCallback(
    (at: number) => {
      const pose = loomPose(at);
      const { done } = pose.weave;
      heddle.current?.setAttribute("transform", translateAlong(P, [0, 0, pose.off]));
      shuttle.current?.setAttribute("transform", SHUTTLE_SIT(pose.weave, pose.off));
      pointer.current?.setAttribute("transform", pointerSlide(done));
      cloth.current?.apply(clothShape(done));
      roll.current?.apply(clothRoll(done));
      clip.current?.setAttribute("d", clothClip(done));
      hole.current?.setAttribute("d", holeWarp(pose.off));
      weft.current?.setAttribute("d", pose.weft);
      comb.current?.setAttribute("d", beaterLines(pose.phi));
      const swung = beaterParts(pose.phi);
      for (let index = 0; index < swung.length; index++) beater[index]?.current?.apply(swung[index]!);

      const text = stateText(pose);
      const host = root.current;
      if (host) {
        const now = String(Math.round(clamp01(at) * 100));
        if (host.getAttribute("aria-valuenow") !== now) {
          host.setAttribute("aria-valuenow", now);
          host.setAttribute("aria-valuetext", text);
        }
      }
    },
    [beater],
  );

  const stop = React.useCallback(() => {
    cancelAnimationFrame(frame.current);
    frame.current = 0;
  }, []);

  const run = React.useCallback(() => {
    if (frame.current) return;
    last.current = 0;
    const step = (now: number) => {
      const dt = last.current ? Math.min((now - last.current) / 1000, MOST_DT) : 1 / 60;
      last.current = now;
      const calm = asksForStillness();
      const s = state.current;
      const still = fixedRef.current;
      const alive = playRef.current && !calm;
      if (still !== null) {
        s.at = still;
        s.want = still;
      } else {
        if (alive) {
          s.clock += dt;
          s.want = tourAt(s.clock);
        }
        s.at = calm ? s.want : follow(s.at, s.want, dt, SEEK);
      }
      draw(s.at);
      frame.current = still !== null || alive || s.at !== s.want ? requestAnimationFrame(step) : 0;
    };
    frame.current = requestAnimationFrame(step);
  }, [draw]);

  const seekTo = React.useCallback(
    (next: number) => {
      state.current.want = clamp01(next);
      run();
    },
    [run],
  );

  React.useEffect(() => {
    if (inView) run();
    else stop();
  }, [inView, run, stop]);

  React.useEffect(() => {
    playRef.current = playing;
    if (fixedRef.current !== null) return;
    const s = state.current;
    if (playing) {
      // pick the tour up where the reader left the shuttle
      s.clock = clockFor(s.at);
    } else {
      // put the loom down where it stands, and let the reader take it from there
      s.want = s.at;
    }
    if (playing && inView) run();
  }, [playing, inView, run]);

  React.useEffect(() => () => stop(), [stop]);
  React.useEffect(() => draw(state.current.at), [draw]);

  /* reduced motion: hold the frame the drawing is about — the cloth well along,
     the shuttle in the air — and let the reader take it from there */
  const stillness = useStillness();
  React.useEffect(() => {
    if (!stillness || fixedRef.current !== null) return;
    const s = state.current;
    s.at = SHOWN;
    s.want = SHOWN;
    draw(SHOWN);
  }, [stillness, draw]);

  /** the pointer's place, read back onto the bed the cloth lies on: the drag
      runs along the warp, so pulling forward draws the cloth off the fell */
  const atFrom = (clientX: number, clientY: number) => {
    const box = root.current?.getBoundingClientRect();
    if (!box || !box.width || !box.height) return null;
    const flat = planeFrom([((clientX - box.left) / box.width) * WIDTH, ((clientY - box.top) / box.height) * HEIGHT], P, BED_Z);
    return clamp01((flat[1] - FELL_Y) / CLOTH_LEN);
  };

  return (
    <div className={className ? `iso the-loom ${className}` : "iso the-loom"} data-theme={theme}>
      <div className="the-loom-plate">
        <div
          ref={root}
          className="the-loom-stage"
          role="slider"
          tabIndex={playing ? -1 : 0}
          data-interactive={playing ? undefined : ""}
          aria-label="A wooden table loom in isometric view. One number drives it, how much cloth has been woven: the shuttle flies the open shed, the rigid heddle lifts half the warp and drops the other half, the beater swings back and carries each row onto the fell, and the cloth grows forward toward the cloth beam. Pause it to draw the cloth off the fell yourself, or to step it a row at a time."
          aria-readonly={playing}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.round(SHOWN * 100)}
          aria-valuetext={stateText(STILL)}
          style={{ touchAction: "pan-y" }}
          onPointerDown={(event) => {
            if (playing) return;
            const at = atFrom(event.clientX, event.clientY);
            if (at === null) return;
            event.currentTarget.setPointerCapture(event.pointerId);
            // hold the cloth where it stands rather than throwing it at the pointer
            grab.current = state.current.want - at;
            setPressing(true);
          }}
          onPointerMove={(event) => {
            if (playing || !pressing) return;
            const at = atFrom(event.clientX, event.clientY);
            if (at === null) return;
            seekTo(at + grab.current);
          }}
          onPointerUp={(event) => {
            if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
            setPressing(false);
          }}
          onPointerCancel={() => setPressing(false)}
          onKeyDown={(event) => {
            if (playing) return;
            const step = event.shiftKey ? 1 / (ROWS * 4) : 1 / ROWS;
            let next: number | null = null;
            if (event.key === "ArrowLeft" || event.key === "ArrowDown") next = state.current.want - step;
            else if (event.key === "ArrowRight" || event.key === "ArrowUp") next = state.current.want + step;
            else if (event.key === "Home") next = 0;
            else if (event.key === "End") next = 1;
            if (next === null) return;
            event.preventDefault();
            seekTo(next);
          }}
        >
          <IsoFigure
            width={WIDTH}
            height={HEIGHT}
            className="the-loom-figure"
            label="A wooden table loom in isometric view: the warp runs back to a beam, the rigid heddle lifts half of it, the shuttle flies the shed, the beater carries each row onto the fell, and the cloth grows forward toward the cloth beam"
          >
            <defs>
              <clipPath id={CLIP}>
                <path ref={clip} d={clothClip(0)} />
              </clipPath>
            </defs>

            <path className="iso-halo" d={HALO} />

            {/* the bench: nothing below the boards moves */}
            {solids(BASE_PARTS, "base")}
            {inks(BASE_LINES, "baseink")}

            {/* the two side boards, the three posts a side, the top rails and the
                housings the beams turn in */}
            {solids(FRAME_PARTS, "frame")}
            {inks(FRAME_LINES, "frameink")}

            {/* the warp beam pays the warp out at the back, behind everything */}
            {solids(WARP_BEAM_PARTS, "warpbeam")}
            {inks(BEAM_LINES, "warpbeamink")}

            {/* the warp: the threads through the heddle's slots never leave the bed */}
            <Line d={SLOT_WARP} tone="lo" />
            {/* and the threads through its holes ride the frame, so they are redrawn */}
            <path ref={hole} className="iso-line" data-tone="lo" d={holeWarp(STILL.off)} />

            {/* the rigid heddle, whole on its guides: slats, frame and the two
                grips the weaver lifts it by */}
            <g ref={heddle}>
              {solids(HEDDLE_PARTS, "hed")}
              {inks(HEDDLE_LINES, "hedink")}
            </g>

            {/* the shuttle rides the lower sheet of the shed, just off the selvage */}
            <g ref={shuttle}>{solids(SHUTTLE_PARTS, "shuttle")}</g>

            {/* the beater: one rigid body on the bar, rebuilt as it swings, and
                the loose weft it carries down onto the fell */}
            {BEATER_STYLE.map((style, index) => (
              <LiveSolid key={`beater${index}`} handle={beater[index]} paths={BEATER_STILL[index]!} tone={style.tone} crease={style.crease} lit={style.lit} />
            ))}
            <path ref={comb} className="iso-line" data-tone="lo" d={COMB_STILL} />
            <path ref={weft} className="iso-line" data-tone="hi" d={STILL.weft} />

            {/* the cloth grows forward from the fell, one beaten row at a time;
                every cell of its weave was written once, and the growing clip
                uncovers it in the order it was woven */}
            <LiveSolid handle={cloth} paths={clothShape(2)} tone="mid" crease="none" className="the-loom-cloth" />
            <g clipPath={`url(#${CLIP})`}>
              <Line d={WEAVE_ALL.weft} tone="lo" />
              <Line d={WEAVE_ALL.warp} tone="mid" />
            </g>

            {/* the cloth beam takes the cloth up at the front, and its roll
                thickens as the cloth comes off the fell */}
            {solids(CLOTH_BEAM_PARTS, "clothbeam")}
            {inks(CLOTH_BEAM_LINES, "clothbeamink")}
            <LiveSolid handle={roll} paths={clothRoll(2)} tone="lo" crease="faint" />

            {/* the row rule on the near board's outer face, and its pointer */}
            {inks(RULE_LINES, "rule")}
            <g ref={pointer}>
              <path className="iso-line" data-tone="hi" d={POINTER_LINE} />
              <Solid paths={POINTER} tone="hi" crease="faint" lit />
            </g>
          </IsoFigure>
        </div>

        <button
          type="button"
          className="the-loom-control"
          aria-label={playing ? "Pause the animation and take the cloth" : "Play the animation"}
          title={playing ? "Pause" : "Play"}
          onClick={() => setPlaying(!playing)}
        >
          <span className="the-loom-swap" aria-hidden="true">
            <HugeiconsIcon className="the-loom-glyph" data-on={playing ? "" : undefined} icon={PauseIcon} size={16} strokeWidth={1.6} />
            <HugeiconsIcon className="the-loom-glyph" data-on={playing ? undefined : ""} icon={PlayIcon} size={16} strokeWidth={1.6} />
          </span>
        </button>
      </div>
    </div>
  );
}

/* The Loom — a wooden table loom on its bench. One number drives the whole
   figure: how much cloth has been woven. The reader gets that one number four
   ways at once. The shuttle flies the open shed, so how far the newest weft has
   crossed the width. The rigid heddle stands up or down, so which half of the
   warp is lifted. The beater swings back to let the shuttle through and forward
   again to pack the row home — and it is the beater that carries the loose weft
   from the shed down onto the fell. And the cloth itself grows forward from the
   fell a beaten row at a time, while the cloth beam fills behind it.

   The warp is Lines; the cloth is a solid that grows. Where warp and weft cross
   the interlace is laid down cell by cell, so the cloth reads as woven cloth and
   not as stripes: the weft rows run the width under everything, and the warp is
   drawn only in the cells where it passes over, so each crossing is one thread
   over the other.

   Nothing is cut away and nothing is transparent. The bench, the two side
   boards, the three posts a side, the beams and their bearing plates are all
   solid, and the heddle is a real rigid heddle: holed slats and open slots
   between them. The one lit part is the shuttle. */
import { circleSection, frameAlong, prismOf, rectSection } from "@/components/anatomy/axis-parts";
import {
  axisVector,
  boxCorners,
  corners,
  cylinder,
  depthOf,
  fitProjection,
  haloOf,
  insetPlan,
  lineOnTop,
  pathOf,
  planOutline,
  pointsAt,
  segment,
  sideRing,
  slabOf,
  type LineTone,
  type Plan,
  type Plane,
  type Point3,
  type Projection,
  type SolidPaths,
  type Tone,
} from "@/components/anatomy/iso-kit";

export const WIDTH = 706;
export const HEIGHT = 574;
const PAD = 20;
/** the camera: a little higher than the kit's default, so the reader looks
    into the loom and the cloth on the bed is not hidden by the near board */
export const ELEVATION = 36;

/* ——— the loom's numbers ———
   The bed is the plane the warp and the cloth lie on. The two side boards stop
   just above it — taller than that and the near board would stand between the
   reader and the cloth — and everything above is carried on three square posts a
   side, so the loom still reads as a frame with a top. */
export const WARP_HALF = 74; // half the width of the warp
export const WARP_N = 30; // threads across it
export const PITCH = 6.4; // one row's depth
export const ROWS = 12; // rows the tour weaves
export const CLOTH_LEN = ROWS * PITCH;

export const BED_Z = 46; // the warp plane
export const CLOTH_H = 4.6; // how thick the cloth stands off it
export const FELL_Z = BED_Z + CLOTH_H;
export const FELL_Y = -8; // the fell: where the warp becomes cloth
export const WARP_FROM_Y = -80; // where the warp leaves the warp beam
export const BEAM_Y = -92; // the warp beam, at the back
export const CLOTH_BEAM_Y = 96; // and the cloth beam, at the front
export const BEAM_R = 9;

export const HED_Y = -46; // the rigid heddle
export const SHED = 9.5; // how far it lifts, either way
const HED_OPEN = 13; // its clear opening, above and below the eye
export const HED_W = 82;

export const SHUTTLE_Y = -28; // the shuttle rides the lower sheet here
export const SHUTTLE_L = 22;
export const SHUTTLE_W = 7.5;
export const SHUTTLE_H = 6;
export const SX0 = -(WARP_HALF - 5); // and coasts just past the selvage
export const SX1 = WARP_HALF - 5;

export const SIDE_IN = 86; // the inside face of the side boards
const SIDE_T = 11;
export const SIDE_OUT = SIDE_IN + SIDE_T;
export const FRAME_Y0 = -110;
export const FRAME_Y1 = 116;
const BOARD_Z0 = 6;
const BOARD_Z1 = 60;
export const POST_Y = [BEAM_Y, -16, CLOTH_BEAM_Y] as const;
const POST_TOP = 100;
const RAIL_Z0 = 86;
const RAIL_Z1 = 100;

export const PIVOT_Y = -16; // the bar the beater hangs from
export const PIVOT_Z = 90;
const REED_Z = 54; // the reed's bottom rail, just clear of the fell
const REED_TOP = 72;
export const REED_W = 80;
const ARM_X = 80;
const BEATER_BACK = 22 * (Math.PI / 180); // the swing, back off the fell
const BEAT_PAST = 3.5 * (Math.PI / 180); // and the lean into the fell on the beat
const RULE_Z = 44; // the row rule, struck on the near board's outer face

const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x);
const smooth01 = (x: number) => {
  const t = clamp01(x);
  return t * t * (3 - 2 * t);
};
const easeInOut = (x: number) => {
  const t = clamp01(x);
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
};

/* ——— one row of weaving, in the order a hand makes it ———
   The beater swings clear, the shuttle flies, the beater comes forward and
   carries the loose weft down onto the fell, and the heddle swaps the shed over
   ready for the next pick. The row turns as the beat lands. */
const BACK_AT = 0.08; // the beater is clear of the shed by here
const CROSS_FROM = 0.08; // and the pick starts once it is
const CROSS_AT = 0.64; // the shuttle is home by here
const BEAT_FROM = 0.64; // now the beater comes forward
const LAND_AT = 0.86; // the beat lands here, and the row joins the cloth
const SWAP_AT = 0.88; // and the shed is over by here

/** The whole of the reader's number: which row, where in it, and which half of
    the warp is lifted for it. Everything the figure draws comes from here. */
export interface Weave {
  at: number;
  row: number; // the row in hand
  done: number; // rows already beaten home
  frac: number; // where in the current row the hand is
  side: number; // nought with the holes down, one with them up
  pick: number; // how far across the newest weft has reached
}

export function weaveAt(at: number): Weave {
  const p = clamp01(at);
  const raw = p * ROWS;
  const done = Math.min(ROWS, Math.floor(raw + 1e-9));
  const row = Math.min(ROWS - 1, done);
  const frac = done >= ROWS ? 1 : raw - row;
  /* a rigid heddle has only the two sheds, so it is one movement from one to the
     next and rests at neither: the frame swings over in the tail of the row */
  const flip = smooth01((frac - SWAP_AT) / (1 - SWAP_AT));
  const swing = (row % 2) + flip;
  return { at: p, row, done, frac, side: 0.5 - 0.5 * Math.cos(Math.PI * swing), pick: smooth01((frac - CROSS_FROM) / (CROSS_AT - CROSS_FROM)) };
}

/** How far the heddle stands off its rest, in world units. */
export const heddleOffset = (weave: Weave) => SHED * (2 * weave.side - 1);

/** The two sheets of the shed at one depth down the warp. The threads through
    the heddle's holes travel with the frame; the threads through its slots stay
    on the bed. Where they cross is the shed the shuttle flies. */
function sheetZ(y: number, off: number) {
  const hole = BED_Z + off + (FELL_Z - BED_Z - off) * ((y - HED_Y) / (FELL_Y - HED_Y));
  const slot = BED_Z + (FELL_Z - BED_Z) * ((y - WARP_FROM_Y) / (FELL_Y - WARP_FROM_Y));
  return { hole, slot, under: Math.min(hole, slot) };
}
/** The shuttle sits on whichever sheet of the shed is the lower one. */
export const shuttleZ = (off: number) => sheetZ(SHUTTLE_Y, off).under;

/* ——— the beater's swing ———
   One rigid body hanging off a bar across the loom. A turn about a horizontal
   line is not a screen matrix, so the beater's parts are rebuilt from swung
   corners every frame, the way the safe's door is. */
export function swingY([x, y, z]: Point3, phi: number): Point3 {
  const cos = Math.cos(phi);
  const sin = Math.sin(phi);
  const dy = y - PIVOT_Y;
  const dz = z - PIVOT_Z;
  return [x, PIVOT_Y + dy * cos - dz * sin, PIVOT_Z + dy * sin + dz * cos];
}
/** The beater's angle: back off the shed while the shuttle flies, forward onto
    the fell to beat, and home again while the heddle swaps over. */
export function beaterAngle(weave: Weave) {
  const { frac } = weave;
  if (frac < BACK_AT) return -BEATER_BACK * smooth01(frac / BACK_AT);
  if (frac < BEAT_FROM) return -BEATER_BACK;
  if (frac < LAND_AT) return -BEATER_BACK + (BEATER_BACK + BEAT_PAST) * easeInOut((frac - BEAT_FROM) / (LAND_AT - BEAT_FROM));
  return BEAT_PAST * (1 - smooth01((frac - LAND_AT) / (1 - LAND_AT)));
}

/** How far across the shed the newest weft has reached, nought at one selvage
    and one at the other; the starting edge swaps every row, as the picks do. */
export const pickFrom = (weave: Weave) => (weave.row % 2 === 0 ? -WARP_HALF : WARP_HALF);
export function weftX(weave: Weave) {
  const start = pickFrom(weave);
  return start + (weave.pick) * (-2 * start);
}
/** The loose weft lies in the shed at the shuttle's own height, and the beater
    carries it down onto the cloth as it beats. */
export function weftY(weave: Weave) {
  if (weave.frac < BEAT_FROM) return SHUTTLE_Y;
  return SHUTTLE_Y + (FELL_Y + PITCH / 2 - SHUTTLE_Y) * easeInOut((weave.frac - BEAT_FROM) / (1 - BEAT_FROM));
}
export function weftZ(weave: Weave, off: number) {
  if (weave.frac < BEAT_FROM) return shuttleZ(off) + SHUTTLE_H * 0.72;
  return shuttleZ(off) + SHUTTLE_H * 0.72 + (FELL_Z + 0.35 - shuttleZ(off) - SHUTTLE_H * 0.72) * easeInOut((weave.frac - BEAT_FROM) / (1 - BEAT_FROM));
}

/* ——— the projection: fitted once, over the extremes of every travel ——— */
function extremes(): Point3[] {
  const out: Point3[] = [];
  const box = (x0: number, x1: number, y0: number, y1: number, z0: number, z1: number) =>
    out.push(...boxCorners({ x: x0, y: y0, w: x1 - x0, d: y1 - y0, r: 0 }, z0, z1));
  box(-SIDE_OUT - 7, SIDE_OUT + 7, FRAME_Y0 - 7, FRAME_Y1 + 7, -18, BOARD_Z0); // the bench and its feet
  box(-SIDE_OUT, SIDE_OUT, FRAME_Y0, FRAME_Y1, BOARD_Z0, RAIL_Z1); // the boards, posts and rails
  box(-SIDE_OUT - 4, SIDE_OUT + 4, BEAM_Y - 17, BEAM_Y + 17, BED_Z - 17, BED_Z + 17); // warp beam and ratchet
  box(-SIDE_OUT - 4, SIDE_OUT + 4, CLOTH_BEAM_Y - 17, CLOTH_BEAM_Y + 17, BED_Z - 17, BED_Z + 17); // cloth beam and its roll
  for (const off of [-SHED, SHED]) box(-HED_W, HED_W, HED_Y - 3, HED_Y + 3, BED_Z + off - HED_OPEN - 6, BED_Z + off + HED_OPEN + 6);
  for (const phi of [0, -BEATER_BACK]) {
    for (const point of [
      [-ARM_X, PIVOT_Y, REED_Z - 5],
      [ARM_X, PIVOT_Y, REED_Z - 5],
      [-REED_W, PIVOT_Y, REED_TOP + 5],
      [REED_W, PIVOT_Y, REED_TOP + 5],
      [-ARM_X, PIVOT_Y - 4, PIVOT_Z + 6],
      [ARM_X, PIVOT_Y + 4, PIVOT_Z + 6],
    ] as Point3[])
      out.push(swingY(point, phi));
  }
  for (const x of [SX0 - SHUTTLE_L / 2, SX1 + SHUTTLE_L / 2])
    box(x, x, SHUTTLE_Y - SHUTTLE_W / 2, SHUTTLE_Y + SHUTTLE_W / 2, BED_Z - SHED - 2, BED_Z + SHED + SHUTTLE_H + 2);
  box(-WARP_HALF, WARP_HALF, FELL_Y, FELL_Y + CLOTH_LEN, BED_Z - 2, FELL_Z + 1); // the cloth, all of it
  box(SIDE_OUT, SIDE_OUT + 6, FELL_Y - 3, FELL_Y + CLOTH_LEN + 3, RULE_Z - 7, RULE_Z + 7); // the row rule
  return out;
}

export const P: Projection = fitProjection(extremes(), WIDTH, HEIGHT, { pad: PAD, elevation: ELEVATION });

/* ——— bars and blocks ——— */
const block = (x0: number, x1: number, y0: number, y1: number, z0: number, z1: number, creases = true): SolidPaths =>
  prismOf(frameAlong([(x0 + x1) / 2, y0, (z0 + z1) / 2], [(x0 + x1) / 2, y1, (z0 + z1) / 2]), rectSection(x1 - x0, z1 - z0), 0, y1 - y0, P, { creases });
const tubeX = (y: number, z: number, x0: number, x1: number, radius: number, steps = 26, creases = false): SolidPaths =>
  prismOf(frameAlong([x0, y, z], [x1, y, z]), circleSection(radius, steps), 0, Math.abs(x1 - x0), P, { creases });
export const bar3 = (from: Point3, to: Point3, width: number, height: number, creases = true): SolidPaths =>
  prismOf(frameAlong(from, to), rectSection(width, height), 0, Math.hypot(to[0] - from[0], to[1] - from[1], to[2] - from[2]), P, { creases });
export const EMPTY: SolidPaths = { fill: "", outline: "", crease: "", top: "", shades: ["", "", "", ""] };

/* ——— what a drawing is made of: a solid, or a line across the faces ——— */
export interface Part {
  paths: SolidPaths;
  tone: Tone;
  crease: Tone | "none";
  lit: boolean;
  mark?: string;
}
export interface Ink {
  d: string;
  tone: LineTone;
  className?: string;
  /** an end meant to stop in the open: only the maker's printed rules */
  free?: boolean;
}
const part = (paths: SolidPaths, tone: Tone = "mid", crease: Tone | "none" = "faint", lit = false, mark?: string): Part => ({ paths, tone, crease, lit, mark });
const ink = (d: string, tone: LineTone = "lo", className?: string, free?: boolean): Ink => ({ d, tone, className, free });

const BENCH: Plan = { x: -SIDE_OUT - 7, y: FRAME_Y0 - 7, w: (SIDE_OUT + 7) * 2, d: FRAME_Y1 - FRAME_Y0 + 14, r: 9 };

/* ——— the bench: nothing below the boards moves ——— */
export const HALO = haloOf(insetPlan(BENCH, -9), -18, 8, P);
export const BASE_PARTS: Part[] = [];
export const BASE_LINES: Ink[] = [];

for (const [x, y] of [...corners(BENCH, 26)].sort((a, b) => depthOf([a[0], a[1], 0], P) - depthOf([b[0], b[1], 0], P))) {
  BASE_PARTS.push(part(cylinder(x, y, 13, -18, 8, P, 22, 1.4), "lo")); // pad
  BASE_PARTS.push(part(cylinder(x, y, 5.4, -10, 16, P, 16), "mid")); // stud
  BASE_PARTS.push(part(cylinder(x, y, 8.2, -4, 6, P, 18, 0.8), "mid")); // lock nut
}
BASE_PARTS.push(part(slabOf(BENCH, 0, 8, P, 12, 1.8), "lo"));
BASE_LINES.push(ink(planOutline(insetPlan(BENCH, 12), 8, P, 12), "faint"));
/* the maker's plate on the bench's front ledge, clear of the boards */
BASE_PARTS.push(part(slabOf({ x: -92, y: FRAME_Y1 - 9, w: 100, d: 12, r: 3 }, 8, 1.3, P, 6, 0.35), "mid"));
for (const [at, width] of [
  [FRAME_Y1 - 5, 32],
  [FRAME_Y1 - 2, 58],
  [FRAME_Y1 + 1, 22],
] as Plane[]) {
  BASE_LINES.push(ink(lineOnTop([-86, at], [-86 + width, at], 9.3, P), "lo", "the-loom-type", true));
}

/* ——— the two side boards, the three posts a side, and the top rails ———
   The boards stop just above the bed so the reader can see over the near one;
   the posts are square and stand on the boards; the rails are tenoned between
   the posts at the two ends. A groove is struck down each board's inner face
   where the heddle's stile runs. */
export const FRAME_PARTS: Part[] = [];
export const FRAME_LINES: Ink[] = [];

for (const side of [-1, 1] as const) {
  const x0 = side < 0 ? -SIDE_OUT : SIDE_IN;
  const x1 = side < 0 ? -SIDE_IN : SIDE_OUT;
  const inner = side < 0 ? -SIDE_IN : SIDE_IN;
  FRAME_PARTS.push(part(block(x0, x1, FRAME_Y0, FRAME_Y1, BOARD_Z0, BOARD_Z1), "mid"));
  FRAME_LINES.push(ink(lineOnTop([inner, FRAME_Y0 + 14], [inner, FRAME_Y1 - 14], BOARD_Z0 + 10, P), "faint", undefined, true));
  /* the heddle's guide: a bracket on the inner face with a groove the stile runs in */
  FRAME_PARTS.push(part(block(Math.min(inner, inner - side * 5), Math.max(inner, inner - side * 5), HED_Y - 13, HED_Y + 13, BED_Z - 17, BED_Z + 17), "mid", "lo"));

  for (const y of POST_Y) {
    FRAME_PARTS.push(part(block(side * (SIDE_IN + 1), side * (SIDE_OUT - 1), y - 6.5, y + 6.5, BOARD_Z1 - 2, POST_TOP), "mid"));
  }
  /* the bearing plates the two beams turn in, on the board's outer face */
  for (const y of [BEAM_Y, CLOTH_BEAM_Y]) {
    const xo = side * SIDE_OUT;
    const xp = side * (SIDE_OUT + 3.4);
    FRAME_PARTS.push(part(block(Math.min(xo, xp), Math.max(xo, xp), y - 13, y + 13, BED_Z - 13, BED_Z + 13), "mid", "lo"));
    FRAME_LINES.push(ink(sideRing([xp, y, BED_Z], 9.6, "x", P, 24), "faint"));
  }
  /* the bar the beater hangs from: a shaft through both posts, with a bearing
     collar at each, so the swing reads as iron turning in the frame */
  FRAME_PARTS.push(part(tubeX(PIVOT_Y, PIVOT_Z, inner, side * (SIDE_OUT + 2), 4.6, 20), "mid", "faint"));
  FRAME_PARTS.push(part(tubeX(PIVOT_Y, PIVOT_Z, side * (SIDE_OUT - 1), side * (SIDE_OUT + 6.5), 7, 22), "mid", "faint"));
  FRAME_LINES.push(ink(sideRing([side * (SIDE_OUT + 6.5), PIVOT_Y, PIVOT_Z], 7, "x", P, 22), "mid"));
}
/* the top rails, tenoned between the posts at the two ends */
for (const y of [BEAM_Y, CLOTH_BEAM_Y]) {
  FRAME_PARTS.push(part(block(-SIDE_IN + 1, SIDE_IN - 1, y - 7.5, y + 7.5, RAIL_Z0, RAIL_Z1), "mid"));
}

/* ——— the two beams ———
   The warp beam pays the warp out at the back, with a ratchet wheel and the
   pawl that holds the warp taut; the cloth beam takes the woven cloth up at the
   front, and its roll thickens as the number grows. They are two lists because
   they sit at opposite ends of the paint order. */
export const WARP_BEAM_PARTS: Part[] = [];
export const CLOTH_BEAM_PARTS: Part[] = [];
export const BEAM_LINES: Ink[] = [];
export const CLOTH_BEAM_LINES: Ink[] = [];

function beam(y: number, geared: boolean, lines: Ink[]): Part[] {
  const out: Part[] = [];
  out.push(part(tubeX(y, BED_Z, -SIDE_IN + 6, SIDE_IN - 6, BEAM_R), "mid", "faint"));
  for (const side of [-1, 1] as const) {
    /* a collar where the beam meets the timber, then the journal carrying on
       past the board, so the beam reads as one piece of iron turning in the
       frame rather than a log lying between two walls */
    out.push(part(tubeX(y, BED_Z, side * (SIDE_IN - 6), side * (SIDE_IN - 22), BEAM_R + 1, 26), "mid", "faint"));
    out.push(part(tubeX(y, BED_Z, side * (SIDE_OUT - 1), side * (SIDE_OUT + 6), 4.8, 18), "mid", "faint"));
    lines.push(ink(sideRing([side * (SIDE_OUT + 6), y, BED_Z], 4.8, "x", P, 18), "faint"));
    if (!geared) continue;
    /* on the warp beam only: a ratchet wheel, and the pawl holding it */
    const xa = side * (SIDE_OUT + 6.4);
    const xb = side * (SIDE_OUT + 10);
    out.push(part(tubeX(y, BED_Z, xa, xb, 11, 26), "mid", "faint"));
    lines.push(ink(sideRing([side * (SIDE_OUT + 10), y, BED_Z], 11, "x", P, 26), "mid"));
    lines.push(ink(sideRing([side * (SIDE_OUT + 10), y, BED_Z], 3, "x", P, 14), "faint"));
    for (let tooth = 0; tooth < 12; tooth++) {
      const a = (tooth / 12) * Math.PI * 2;
      lines.push(ink(segment([side * (SIDE_OUT + 10), y + 6.8 * Math.cos(a), BED_Z + 6.8 * Math.sin(a)], [side * (SIDE_OUT + 10), y + 11 * Math.cos(a), BED_Z + 11 * Math.sin(a)], P), "faint"));
    }
    const px = side * (SIDE_OUT + 8);
    out.push(part(bar3([px, y - 15, BED_Z + 17], [px, y + 6, BED_Z + 9.4], 4.6, 3, true), "mid", "faint"));
    out.push(part(cylinder(px, y - 15, 3.4, BED_Z + 13.6, 6, P, 14, 0.6), "mid", "faint"));
  }
  return out;
}
WARP_BEAM_PARTS.push(...beam(BEAM_Y, true, BEAM_LINES));
CLOTH_BEAM_PARTS.push(...beam(CLOTH_BEAM_Y, false, CLOTH_BEAM_LINES));
/* the warp on the warp beam, and a little already wound on the cloth beam */
WARP_BEAM_PARTS.push(part(tubeX(BEAM_Y, BED_Z, -SIDE_IN + 7, SIDE_IN - 7, BEAM_R + 0.7, 30), "lo", "none"));
CLOTH_BEAM_PARTS.push(part(tubeX(CLOTH_BEAM_Y, BED_Z, -SIDE_IN + 9, SIDE_IN - 9, BEAM_R + 1.6, 30), "lo", "none"));

/* ——— the rigid heddle ———
   One frame with the whole shed in it. Half the warp passes through holes bored
   in the slats and travels with the frame; the other half runs through the open
   slots between them and stays on the bed. There are no other sheds, so the
   frame is always on its way from one to the other. */
export const WARP_XS = Array.from({ length: WARP_N }, (_, index) => -WARP_HALF + (index + 0.5) * ((2 * WARP_HALF) / WARP_N));
export const HOLES = WARP_XS.filter((_, index) => index % 2 === 0);
const SLOTS = WARP_XS.filter((_, index) => index % 2 === 1);

export const HEDDLE_PARTS: Part[] = [];
export const HEDDLE_LINES: Ink[] = [];
HEDDLE_PARTS.push(part(block(-HED_W, HED_W, HED_Y - 4, HED_Y + 4, BED_Z + HED_OPEN, BED_Z + HED_OPEN + 5.4), "hi", "faint"));
HEDDLE_PARTS.push(part(block(-HED_W, HED_W, HED_Y - 4, HED_Y + 4, BED_Z - HED_OPEN - 5.4, BED_Z - HED_OPEN), "hi", "faint"));
for (const side of [-1, 1] as const) {
  const xa = side * (HED_W - 8);
  const xb = side * HED_W;
  HEDDLE_PARTS.push(part(block(Math.min(xa, xb), Math.max(xa, xb), HED_Y - 4, HED_Y + 4, BED_Z - HED_OPEN, BED_Z + HED_OPEN), "mid", "faint"));
}
/* the slats: flat strips standing edge-on to the warp, a hole bored through each */
for (const x of HOLES) {
  HEDDLE_PARTS.push(part(block(x - 1.9, x + 1.9, HED_Y - 0.9, HED_Y + 0.9, BED_Z - HED_OPEN, BED_Z + HED_OPEN, false), "lo", "none"));
  HEDDLE_LINES.push(ink(sideRing([x, HED_Y, BED_Z], 2.5, "y", P, 18), "mid"));
}
HEDDLE_LINES.push(ink(lineOnTop([-HED_W + 8, HED_Y], [HED_W - 8, HED_Y], BED_Z + HED_OPEN, P), "faint", undefined, true));
HEDDLE_LINES.push(ink(lineOnTop([-HED_W + 8, HED_Y], [HED_W - 8, HED_Y], BED_Z - HED_OPEN, P), "faint", undefined, true));

/* ——— the warp: the threads through the slots never leave the bed, the rest
       ride the frame, and the whole set meets the cloth at the fell ——— */
export const SLOT_WARP = SLOTS.map((x) => segment([x, WARP_FROM_Y, BED_Z], [x, FELL_Y, FELL_Z], P)).join("");
export const holeWarp = (off: number) =>
  HOLES.map((x) =>
    segment([x, WARP_FROM_Y, BED_Z], [x, HED_Y, BED_Z + off], P) +
    segment([x, HED_Y, BED_Z + off], [x, FELL_Y, FELL_Z], P),
  ).join("");

/* ——— the cloth ———
   A slab that grows forward from the fell, a beaten row at a time, and the cloth
   beam's roll thickening behind it. The interlace is written once for every row
   the loom will weave, and the newest row sits at the fell where the beater
   lands: as the number grows each row keeps its identity and the cloth appears
   to be drawn forward. */
export const rowY = (id: number) => FELL_Y + (ROWS - 1 - id) * PITCH;
export function clothShape(done: number): SolidPaths {
  if (done < 1) return EMPTY;
  return slabOf({ x: -WARP_HALF, y: FELL_Y, w: 2 * WARP_HALF, d: done * PITCH, r: 1.4 }, BED_Z, CLOTH_H, P, 3, 0.5);
}
export function clothClip(done: number) {
  const front = FELL_Y + Math.max(0, done) * PITCH;
  return pathOf(pointsAt([[-WARP_HALF, FELL_Y, FELL_Z], [WARP_HALF, FELL_Y, FELL_Z], [WARP_HALF, front, FELL_Z], [-WARP_HALF, front, FELL_Z]], P), true);
}
export function clothRoll(done: number): SolidPaths {
  return tubeX(CLOTH_BEAM_Y, BED_Z, -SIDE_IN + 9, SIDE_IN - 9, BEAM_R + 1.6 + done * 0.34, 30);
}
/** Every cell of the weave for the rows already beaten home. The weft row runs
    the width under everything; the warp is drawn only where it passes over, so
    each crossing is one thread over the other and the cloth is cloth. */
export function weaveInk(done: number) {
  const weft: string[] = [];
  const warp: string[] = [];
  for (let id = 0; id < done; id++) {
    const y0 = rowY(id);
    weft.push(segment([-WARP_HALF, y0 + PITCH / 2, FELL_Z + 0.35], [WARP_HALF, y0 + PITCH / 2, FELL_Z + 0.35], P));
    for (let index = 0; index < WARP_N; index++) {
      if ((id + index) % 2) continue;
      warp.push(segment([WARP_XS[index], y0, FELL_Z + 0.9], [WARP_XS[index], y0 + PITCH, FELL_Z + 0.9], P));
    }
  }
  return { weft: weft.join(""), warp: warp.join("") };
}
/** The whole weave, written once for every row the loom will ever weave. The
    newest row sits at the fell, so a clip that grows forward one row at a time
    uncovers the cloth in the order it was woven. */
export const WEAVE_ALL = weaveInk(ROWS);

/* ——— the loose weft, and the row in hand ———
   It leaves the shuttle in the shed and the beater carries it down onto the
   fell, which is the whole of what a beat is. */
export function liveWeft(weave: Weave, off: number) {
  if (weave.done >= ROWS) return "";
  const x = weftX(weave);
  const start = pickFrom(weave);
  const [a, b] = start < x ? [start, x] : [x, start];
  const y = weftY(weave);
  const z = weftZ(weave, off);
  return segment([a, y, z], [b, y, z], P);
}

/* ——— the shuttle: a boat that rests on whichever sheet of the shed is lower,
       so it steps down when the heddle drops ——— */
export const SHUTTLE_BODY = slabOf({ x: -SHUTTLE_L / 2, y: SHUTTLE_Y - SHUTTLE_W / 2, w: SHUTTLE_L, d: SHUTTLE_W, r: 3.2 }, 0, SHUTTLE_H, P, 12, 0.9);
export const SHUTTLE_WELL = slabOf({ x: -SHUTTLE_L / 2 + 4.5, y: SHUTTLE_Y - 2.2, w: SHUTTLE_L - 9, d: 4.4, r: 1.5 }, SHUTTLE_H - 1.6, 1.6, P, 6, 0.35);
export const SHUTTLE_BOBBIN = tubeX(SHUTTLE_Y, SHUTTLE_H - 0.8, -SHUTTLE_L / 2 + 7.5, SHUTTLE_L / 2 - 7.5, 2, 14);
export const SHUTTLE_TIPS = [
  tubeX(SHUTTLE_Y, SHUTTLE_H / 2, -SHUTTLE_L / 2, -SHUTTLE_L / 2 + 3, 3.4, 14),
  tubeX(SHUTTLE_Y, SHUTTLE_H / 2, SHUTTLE_L / 2 - 3, SHUTTLE_L / 2, 3.4, 14),
];
export const SHUTTLE_PARTS: Part[] = [
  part(SHUTTLE_BODY, "hi", "faint", true),
  part(SHUTTLE_WELL, "lo", "none"),
  part(SHUTTLE_BOBBIN, "hi", "faint"),
  part(SHUTTLE_TIPS[0], "mid", "faint"),
  part(SHUTTLE_TIPS[1], "mid", "faint"),
];
export const SHUTTLE_SIT = (weave: Weave, off: number) => `translate(${sitX(weave).toFixed(2)} ${sitY(off).toFixed(2)})`;
const sitX = (weave: Weave) => axisVector(P, [weftX(weave), 0, 0])[0];
const sitY = (off: number) => axisVector(P, [0, 0, shuttleZ(off)])[1];

/* ——— the beater: one rigid body on the bar, rebuilt as it swings ——— */
export function beaterParts(phi: number): SolidPaths[] {
  const swept = (a: Point3, b: Point3, section: Plane[], creases = true) =>
    prismOf(frameAlong(swingY(a, phi), swingY(b, phi)), section, 0, Math.hypot(b[0] - a[0], b[1] - a[1], b[2] - a[2]), P, { creases });
  return [
    swept([-ARM_X, PIVOT_Y, REED_Z - 6], [-ARM_X, PIVOT_Y, PIVOT_Z + 1], rectSection(5.6, 6.6)),
    swept([ARM_X, PIVOT_Y, REED_Z - 6], [ARM_X, PIVOT_Y, PIVOT_Z + 1], rectSection(5.6, 6.6)),
    swept([-REED_W, PIVOT_Y, REED_Z], [REED_W, PIVOT_Y, REED_Z], rectSection(6, 7)),
    swept([-REED_W, PIVOT_Y, REED_TOP], [REED_W, PIVOT_Y, REED_TOP], rectSection(6, 7)),
    swept([-ARM_X, PIVOT_Y, PIVOT_Z], [-ARM_X + 5.4, PIVOT_Y, PIVOT_Z], circleSection(5.4, 16), false),
    swept([ARM_X - 5.4, PIVOT_Y, PIVOT_Z], [ARM_X, PIVOT_Y, PIVOT_Z], circleSection(5.4, 16), false),
  ];
}
/** The reed: a close-set comb, which is what actually packs the weft. */
export function beaterLines(phi: number) {
  const out: string[] = [];
  for (let x = -REED_W + 6; x <= REED_W - 6 + 0.01; x += 6) {
    out.push(segment(swingY([x, PIVOT_Y, REED_Z + 3.4], phi), swingY([x, PIVOT_Y, REED_TOP - 3.4], phi), P));
  }
  return out.join("");
}
export const BEATER_STYLE: Array<Pick<Part, "tone" | "crease" | "lit">> = [
  { tone: "mid", crease: "faint", lit: false },
  { tone: "mid", crease: "faint", lit: false },
  { tone: "mid", crease: "faint", lit: false },
  { tone: "mid", crease: "faint", lit: false },
  { tone: "lo", crease: "faint", lit: false },
  { tone: "lo", crease: "faint", lit: false },
];

/* ——— the row rule on the near board's outer face, and the pointer that marks
       how much cloth has come off the fell ——— */
export const RULE_LINES: Ink[] = [];
export const RULE_EDGE = SIDE_OUT + 0.5;
for (const z of [RULE_Z + 7.2, RULE_Z - 7.2]) {
  RULE_LINES.push(ink(segment([RULE_EDGE, FELL_Y - 4, z], [RULE_EDGE, FELL_Y + CLOTH_LEN + 4, z], P), "faint"));
}
for (let row = 0; row <= ROWS; row++) {
  const y = FELL_Y + row * PITCH;
  const long = row % 6 === 0;
  RULE_LINES.push(ink(segment([RULE_EDGE, y, RULE_Z + (long ? 6 : 3)], [RULE_EDGE, y, RULE_Z - (long ? 6 : 3)], P), long ? "lo" : "faint"));
}
export const POINTER = slabOf({ x: SIDE_OUT - 1.5, y: -4, w: 5.5, d: 8, r: 1 }, RULE_Z - 4.6, 9.2, P, 5, 0.6);
export const POINTER_LINE = segment([SIDE_OUT + 4.4, 0, RULE_Z + 4.6], [SIDE_OUT + 4.4, 0, RULE_Z - 4.6], P);
export function pointerSlide(done: number) {
  const [x, y] = axisVector(P, [0, FELL_Y + done * PITCH, 0]);
  return `translate(${x.toFixed(2)} ${y.toFixed(2)})`;
}

/* ——— the reader's number, gathered: everything the figure draws comes from
       this one pose ——— */
export interface LoomPose {
  weave: Weave;
  off: number;
  phi: number;
  weft: string;
}
export function loomPose(at: number): LoomPose {
  const weave = weaveAt(at);
  const off = heddleOffset(weave);
  return { weave, off, phi: beaterAngle(weave), weft: liveWeft(weave, off) };
}

/* ——— the tour ———
   The tour weaves the whole cloth, holds it up, and then winds it back onto the
   cloth beam so the figure loops. The wind-back is the same number read
   backwards: the shuttle glides home, the heddle levels and the cloth shortens. */
export const WEAVE_TIME = 26;
const HOLD = 2;
const WIND = 4;
export const PERIOD = WEAVE_TIME + HOLD + WIND + HOLD;

export function tourAt(clock: number) {
  const t = ((clock % PERIOD) + PERIOD) % PERIOD;
  if (t < WEAVE_TIME) return t / WEAVE_TIME;
  if (t < WEAVE_TIME + HOLD) return 1;
  if (t < WEAVE_TIME + HOLD + WIND) return 1 - easeInOut((t - WEAVE_TIME - HOLD) / WIND);
  return 0;
}
/** Where in the tour to set off from, so play never jumps. */
export const clockFor = (at: number) => (clamp01(at) >= 1 ? WEAVE_TIME + HOLD : clamp01(at) * WEAVE_TIME);

/** The state the drawing is in, in words: the one number, read out. */
export function stateText(pose: LoomPose) {
  const { weave } = pose;
  if (weave.done >= ROWS) return `${ROWS}/${ROWS} rows · cloth woven`;
  const shed = weave.side > 0.5 ? "up" : "down";
  return `row ${weave.done + 1}/${ROWS} · shed ${shed} · pick ${Math.round(weave.pick * 100)}%`;
}

/* The Loom — the framed plate the figure sits in and the play/pause control.
   The only chrome the figure needs; the drawing is styled by iso.css. */

.the-loom {
  --the-loom-pad: clamp(16px, 4.5vw, 34px);
}

.the-loom-plate {
  position: relative;
  background: var(--anatomy-card);
  /* the figure's solids are filled with --anatomy-paper, which has to match
     the surface they are drawn on or every body shows a lighter rectangle */
  --anatomy-paper: var(--anatomy-card);
  box-shadow: 0 0 0 1px var(--anatomy-mid);
  padding: var(--the-loom-pad);
}

.the-loom-stage {
  outline: none;
}

/* the pointer is only a handle while the tour is stopped: it draws the cloth
   off the fell, along the warp */
.the-loom-stage[data-interactive] {
  cursor: ew-resize;
}

.the-loom-stage[data-interactive]:active {
  cursor: grabbing;
}

/* the maker's lettering, punched into the bench: short rules that read as type
   at this size rather than real text */
.the-loom-type {
  stroke-width: 1.1;
}

/* the cloth is the one mass the drawing lifts off the card: its top face and
   its lit flanks take the kit's brightest fills, so the cloth reads as cloth
   and the frame around it stays quiet. No lit edge: the weave carries it. */
.the-loom-cloth > .iso-top {
  fill: var(--anatomy-lit-top);
}

.the-loom-cloth > .iso-shade {
  fill: var(--anatomy-lit-shade);
}

.the-loom-control {
  position: absolute;
  top: calc(var(--the-loom-pad) - 8px);
  right: calc(var(--the-loom-pad) - 8px);
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid var(--anatomy-mid);
  border-radius: 999px;
  background: var(--anatomy-card);
  color: var(--anatomy-hi);
  cursor: pointer;
  transition:
    border-color 160ms var(--anatomy-ease),
    color 160ms var(--anatomy-ease),
    transform 160ms var(--anatomy-ease);
}

/* hover only where a pointer can hover: a tap latches :hover */
@media (hover: hover) {
  .the-loom-control:hover {
    border-color: var(--anatomy-hi);
    color: var(--anatomy-strong);
  }
}

.the-loom-control:active {
  transform: translateY(0.5px);
}

.the-loom-control svg {
  display: block;
}

/* the icon-swap recipe: both glyphs stay in the one cell and cross-fade, so the
   swap is scale 0.25 -> 1, blur 4px -> 0 over 300ms. No motion library needed. */
.the-loom-swap {
  position: relative;
  display: grid;
  place-items: center;
  width: 16px;
  height: 16px;
}

.the-loom-glyph {
  grid-area: 1 / 1;
  opacity: 0;
  filter: blur(4px);
  transform: scale(0.25);
  transition:
    opacity 300ms cubic-bezier(0.2, 0, 0, 1),
    filter 300ms cubic-bezier(0.2, 0, 0, 1),
    transform 300ms cubic-bezier(0.2, 0, 0, 1);
}

.the-loom-glyph[data-on] {
  opacity: 1;
  filter: blur(0);
  transform: scale(1);
}

.the-loom :focus-visible {
  outline: 1px solid var(--anatomy-hi);
  outline-offset: 4px;
}

@media (prefers-reduced-motion: reduce) {
  .the-loom-control {
    transition: none;
  }
  /* keep the fade, drop the movement */
  .the-loom-glyph,
  .the-loom-glyph[data-on] {
    transition: opacity 150ms ease-out;
    filter: none;
    transform: none;
  }
}

export type Flat = [number, number];
export type Point3 = [number, number, number];
export type Plane = [number, number];

export interface Projection {
  origin: Flat;
  scale: number;
  azimuth?: number;
  elevation?: number;
}

export interface Plan {
  x: number;
  y: number;
  w: number;
  d: number;
  r: number;
}

export interface SolidPaths {
  fill: string;
  outline: string;
  crease: string;
  top: string;
  shades: string[];
  bevel?: string;
  seamless?: boolean;
}

export type Tone = "hi" | "mid" | "lo" | "faint";
export type LineTone = Tone | "lit" | "red" | "green" | "blue";

export const AZIMUTH = 45;
export const ELEVATION = 30;
export const SHADES = 4;

const RADIANS = Math.PI / 180;
const UNIT = Math.sqrt(1.6);

interface Camera {
  sinA: number;
  cosA: number;
  sinE: number;
  cosE: number;
  k: number;
}

export function cameraOf({ scale, azimuth = AZIMUTH, elevation = ELEVATION }: Projection): Camera {
  const a = azimuth * RADIANS;
  const e = elevation * RADIANS;
  return { sinA: Math.sin(a), cosA: Math.cos(a), sinE: Math.sin(e), cosE: Math.cos(e), k: scale * UNIT };
}

export function iso([x, y, z]: Point3, projection: Projection): Flat {
  const { origin } = projection;
  const { sinA, cosA, sinE, cosE, k } = cameraOf(projection);
  return [origin[0] + (x * sinA - y * cosA) * k, origin[1] + ((x * cosA + y * sinA) * sinE - z * cosE) * k];
}

export function towardViewer(projection: Projection): Plane {
  const { sinA, cosA } = cameraOf(projection);
  return [cosA, sinA];
}

export function depthOf([x, y, z]: Point3, projection: Projection) {
  const { sinA, cosA, sinE, cosE } = cameraOf(projection);
  return (x * cosA + y * sinA) * cosE + z * sinE;
}

const tenth = (value: number) => {
  const text = (Math.round(value * 10) / 10).toFixed(1).replace(/\.0$/, "");
  return text === "-0" ? "0" : text;
};

export function pathOf(points: Flat[], closed = false) {
  if (!points.length) return "";
  return points.map(([x, y], at) => `${at ? "L" : "M"}${tenth(x)} ${tenth(y)}`).join("") + (closed ? "Z" : "");
}

export const joinPaths = (paths: string[]) => paths.filter(Boolean).join("");

export function roundedPlan({ x, y, w, d, r }: Plan, steps = 8): Plane[] {
  const radius = Math.max(0, Math.min(r, w / 2, d / 2));
  const corners: [number, number, number][] = [
    [x + w - radius, y + radius, -90],
    [x + w - radius, y + d - radius, 0],
    [x + radius, y + d - radius, 90],
    [x + radius, y + radius, 180],
  ];
  const out: Plane[] = [];
  for (const [cx, cy, start] of corners) {
    const count = radius > 0 ? steps : 0;
    for (let step = 0; step <= count; step++) {
      const angle = (start + (count ? (90 * step) / count : 45)) * RADIANS;
      out.push([cx + radius * Math.cos(angle), cy + radius * Math.sin(angle)]);
    }
  }
  return out;
}

function signedArea(points: Plane[] | Flat[]) {
  let area = 0;
  for (let index = 0; index < points.length; index++) {
    const [ax, ay] = points[index]!;
    const [bx, by] = points[(index + 1) % points.length]!;
    area += ax * by - bx * ay;
  }
  return area / 2;
}

const oriented = (points: Flat[]) => (signedArea(points) < 0 ? [...points].reverse() : points);

function convexHull(points: Flat[]): Flat[] {
  const sorted = [...points].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  if (sorted.length < 3) return sorted;
  const cross = (o: Flat, a: Flat, b: Flat) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lower: Flat[] = [];
  for (const point of sorted) {
    while (lower.length >= 2 && cross(lower[lower.length - 2]!, lower[lower.length - 1]!, point) <= 0) lower.pop();
    lower.push(point);
  }
  const upper: Flat[] = [];
  for (let index = sorted.length - 1; index >= 0; index--) {
    const point = sorted[index]!;
    while (upper.length >= 2 && cross(upper[upper.length - 2]!, upper[upper.length - 1]!, point) <= 0) upper.pop();
    upper.push(point);
  }
  return [...lower.slice(0, -1), ...upper.slice(0, -1)];
}

function runsOf(flags: boolean[], want: boolean) {
  const count = flags.length;
  const runs: number[][] = [];
  const start = flags.findIndex((flag, index) => flag !== flags[(index + count - 1) % count]);
  if (start < 0) return flags[0] === want ? [Array.from({ length: count + 1 }, (_, index) => index % count)] : [];
  let run: number[] | null = null;
  for (let step = 0; step < count; step++) {
    const index = (start + step) % count;
    if (flags[index] === want) {
      if (!run) run = [index];
      run.push((index + 1) % count);
    } else if (run) {
      runs.push(run);
      run = null;
    }
  }
  if (run) runs.push(run);
  return runs;
}

export interface ExtrudeOptions {
  convex?: boolean;
  bevel?: number;
}

export function extrude(ring: Plane[], z: number, height: number, projection: Projection, options: ExtrudeOptions = {}): SolidPaths {
  const convex = options.convex ?? true;
  const count = ring.length;
  const counter = signedArea(ring) > 0;
  const [vx, vy] = towardViewer(projection);
  const { sinA, cosA } = cameraOf(projection);
  const normals = ring.map(([ax, ay], index) => {
    const [bx, by] = ring[(index + 1) % count]!;
    const dx = bx - ax;
    const dy = by - ay;
    const length = Math.hypot(dx, dy) || 1;
    return (counter ? [dy / length, -dx / length] : [-dy / length, dx / length]) as Plane;
  });
  const facing = normals.map(([nx, ny]) => nx * vx + ny * vy > 1e-9);
  const top = ring.map(([x, y]) => iso([x, y, z + height], projection));
  const bottom = ring.map(([x, y]) => iso([x, y, z], projection));
  const outline: string[] = [];
  const crease: string[] = [];
  for (const run of runsOf(facing, false)) outline.push(pathOf(run.map((index) => top[index]!)));
  for (const run of runsOf(facing, true)) {
    crease.push(pathOf(run.map((index) => top[index]!)));
    if (height > 0) outline.push(pathOf(run.map((index) => bottom[index]!)));
  }
  if (height > 0) {
    for (let index = 0; index < count; index++) {
      if (facing[(index + count - 1) % count] !== facing[index]) outline.push(pathOf([top[index]!, bottom[index]!]));
    }
  }
  let fill: string;
  if (convex) {
    fill = pathOf(convexHull([...top, ...bottom]), true);
  } else {
    const parts = [pathOf(oriented(top), true), pathOf(oriented(bottom), true)];
    for (let index = 0; index < count; index++) {
      if (!facing[index]) continue;
      const next = (index + 1) % count;
      parts.push(pathOf(oriented([top[index]!, top[next]!, bottom[next]!, bottom[index]!]), true));
    }
    fill = parts.join("");
  }
  const buckets: string[][] = Array.from({ length: SHADES }, () => []);
  if (height > 0) {
    const [lx, ly] = [-sinA, cosA];
    for (let index = 0; index < count; index++) {
      if (!facing[index]) continue;
      const [nx, ny] = normals[index]!;
      const lit = (nx * lx + ny * ly + 1) / 2;
      const shade = Math.min(SHADES - 1, Math.max(0, Math.floor(lit * SHADES)));
      const next = (index + 1) % count;
      buckets[shade]!.push(pathOf(oriented([top[index]!, top[next]!, bottom[next]!, bottom[index]!]), true));
    }
  }
  let bevel: string | undefined;
  if (options.bevel && options.bevel > 0) {
    const by = options.bevel;
    const inset = ring.map(([x, y], index) => {
      const [ax, ay] = normals[(index + count - 1) % count]!;
      const [bx, by2] = normals[index]!;
      const mx = ax + bx;
      const my = ay + by2;
      const length = Math.hypot(mx, my) || 1;
      return [x - (mx / length) * by, y - (my / length) * by] as Plane;
    });
    const insetTop = inset.map(([x, y]) => iso([x, y, z + height], projection));
    bevel = runsOf(facing, true)
      .map((run) => pathOf([top[run[0]!]!, ...run.slice(1, -1).map((index) => insetTop[index]!), top[run[run.length - 1]!]!]))
      .join("");
  }
  return {
    fill,
    outline: outline.join(""),
    crease: crease.join(""),
    top: pathOf(oriented(top), true),
    shades: buckets.map((paths) => paths.join("")),
    bevel,
  };
}

export const ringOf = (plan: Plan, steps = 8): Plane[] => roundedPlan(plan, steps);

export function slabOf(plan: Plan, z: number, height: number, projection: Projection, steps = 8, bevel = 0) {
  return extrude(ringOf(plan, steps), z, height, projection, { convex: true, bevel });
}

export function circleRing(cx: number, cy: number, radius: number, steps = 40): Plane[] {
  return Array.from({ length: steps }, (_, step) => {
    const angle = (step / steps) * Math.PI * 2;
    return [cx + radius * Math.cos(angle), cy + radius * Math.sin(angle)] as Plane;
  });
}

export function cylinder(cx: number, cy: number, radius: number, z: number, height: number, projection: Projection, steps = 32, bevel = 0) {
  return extrude(circleRing(cx, cy, radius, steps), z, height, projection, { convex: true, bevel });
}

export const insetPlan = ({ x, y, w, d, r }: Plan, by: number): Plan => ({ x: x + by, y: y + by, w: w - by * 2, d: d - by * 2, r: Math.max(0, r - by) });

export function onTop(points: Plane[], z: number, projection: Projection, closed = false) {
  return pathOf(
    points.map(([x, y]) => iso([x, y, z], projection)),
    closed,
  );
}

export const planOutline = (plan: Plan, z: number, projection: Projection, steps = 8) => onTop(ringOf(plan, steps), z, projection, true);

export const lineOnTop = (from: Plane, to: Plane, z: number, projection: Projection) => onTop([from, to], z, projection);

export const segment = (from: Point3, to: Point3, projection: Projection) => pathOf([iso(from, projection), iso(to, projection)]);

export const rise = (at: Plane, from: number, to: number, projection: Projection) => segment([at[0], at[1], from], [at[0], at[1], to], projection);

export const ring = (cx: number, cy: number, radius: number, z: number, projection: Projection, steps = 40) =>
  onTop(circleRing(cx, cy, radius, steps), z, projection, true);

export const pointsAt = (points: Point3[], projection: Projection): Flat[] => points.map((point) => iso(point, projection));

export function dotGrid(x: number, y: number, columns: number, rows: number, gap: number, z: number, projection: Projection): Flat[] {
  const dots: Flat[] = [];
  for (let row = 0; row < rows; row++) {
    for (let column = 0; column < columns; column++) dots.push(iso([x + column * gap, y + row * gap, z], projection));
  }
  return dots;
}

export function corners({ x, y, w, d }: Plan, inset = 0): Plane[] {
  return [
    [x + inset, y + inset],
    [x + w - inset, y + inset],
    [x + inset, y + d - inset],
    [x + w - inset, y + d - inset],
  ];
}

export function boxCorners({ x, y, w, d }: Plan, z0: number, z1: number): Point3[] {
  const out: Point3[] = [];
  for (const px of [x, x + w]) for (const py of [y, y + d]) for (const z of [z0, z1]) out.push([px, py, z]);
  return out;
}

export function knurl(cx: number, cy: number, radius: number, z0: number, z1: number, count: number, projection: Projection, inset = 0.4) {
  const [vx, vy] = towardViewer(projection);
  const lines: string[] = [];
  for (let index = 0; index < count; index++) {
    const angle = (index / count) * Math.PI * 2;
    const nx = Math.cos(angle);
    const ny = Math.sin(angle);
    if (nx * vx + ny * vy < 0.15) continue;
    lines.push(segment([cx + radius * nx, cy + radius * ny, z0 + inset], [cx + radius * nx, cy + radius * ny, z1 - inset], projection));
  }
  return lines.join("");
}

export function sideArc(cx: number, cy: number, radius: number, z: number, projection: Projection, steps = 24) {
  const [vx, vy] = towardViewer(projection);
  const facing = Math.atan2(vy, vx);
  const points: Flat[] = [];
  for (let step = 0; step <= steps; step++) {
    const angle = facing - Math.PI / 2 + (step / steps) * Math.PI;
    points.push(iso([cx + radius * Math.cos(angle), cy + radius * Math.sin(angle), z], projection));
  }
  return pathOf(points);
}

export function ringSeam(ring: Plane[], z: number, projection: Projection) {
  const count = ring.length;
  const counter = signedArea(ring) > 0;
  const [vx, vy] = towardViewer(projection);
  const facing = ring.map(([ax, ay], index) => {
    const [bx, by] = ring[(index + 1) % count];
    const dx = bx - ax;
    const dy = by - ay;
    const [nx, ny] = counter ? [dy, -dx] : [-dy, dx];
    return nx * vx + ny * vy > 1e-9;
  });
  return runsOf(facing, true).map((run) => pathOf(run.map((index) => iso([ring[index][0], ring[index][1], z], projection)))).join("");
}

export const sideSeam = (plan: Plan, z: number, projection: Projection, steps = 8) => ringSeam(ringOf(plan, steps), z, projection);

export function sideRing(center: Point3, radius: number, axis: "x" | "y", projection: Projection, steps = 20) {
  const [px, py, pz] = center;
  const points: Flat[] = [];
  for (let step = 0; step < steps; step++) {
    const angle = (step / steps) * Math.PI * 2;
    const u = radius * Math.cos(angle);
    const v = radius * Math.sin(angle);
    points.push(iso(axis === "x" ? [px, py + u, pz + v] : [px + u, py, pz + v], projection));
  }
  return pathOf(points, true);
}

export function coil(from: number, to: number, center: Plane, radius: number, turns: number, axis: "x" | "y", projection: Projection, perTurn = 16) {
  const count = Math.max(1, Math.round(turns * perTurn));
  const back: string[] = [];
  const front: string[] = [];
  let run: Flat[] = [];
  let near: boolean | null = null;
  for (let index = 0; index <= count; index++) {
    const share = index / count;
    const angle = share * turns * Math.PI * 2;
    const u = radius * Math.cos(angle);
    const v = radius * Math.sin(angle);
    const along = from + (to - from) * share;
    const point: Point3 = axis === "x" ? [along, center[0] + u, center[1] + v] : [center[0] + u, along, center[1] + v];
    const normal: Point3 = axis === "x" ? [0, Math.cos(angle), Math.sin(angle)] : [Math.cos(angle), 0, Math.sin(angle)];
    const facing = depthOf(normal, projection) > 0;
    const flat = iso(point, projection);
    if (near === null) near = facing;
    if (facing !== near) {
      run.push(flat);
      (near ? front : back).push(pathOf(run));
      run = [flat];
      near = facing;
      continue;
    }
    run.push(flat);
  }
  if (run.length > 1) (near ? front : back).push(pathOf(run));
  return { back: back.join(""), front: front.join("") };
}

export interface Ticks {
  minor: string;
  major: string;
}

export function topTicks(from: number, to: number, step: number, every: number, edge: number, z: number, lengths: [number, number], projection: Projection, axis: "x" | "y" = "x"): Ticks {
  const minor: string[] = [];
  const major: string[] = [];
  const first = Math.ceil(from / step) * step;
  for (let at = first, index = Math.round(first / step); at <= to + 1e-9; at += step, index++) {
    const big = index % every === 0;
    const length = big ? lengths[1] : lengths[0];
    const a: Plane = axis === "x" ? [at, edge] : [edge, at];
    const b: Plane = axis === "x" ? [at, edge + length] : [edge + length, at];
    (big ? major : minor).push(lineOnTop(a, b, z, projection));
  }
  return { minor: minor.join(""), major: major.join("") };
}

export function sideTicks(from: number, to: number, step: number, every: number, face: number, top: number, lengths: [number, number], projection: Projection, axis: "x" | "y" = "x"): Ticks {
  const minor: string[] = [];
  const major: string[] = [];
  const first = Math.ceil(from / step) * step;
  for (let at = first, index = Math.round(first / step); at <= to + 1e-9; at += step, index++) {
    const big = index % every === 0;
    const length = big ? lengths[1] : lengths[0];
    const a: Point3 = axis === "x" ? [at, face, top] : [face, at, top];
    const b: Point3 = axis === "x" ? [at, face, top - length] : [face, at, top - length];
    (big ? major : minor).push(segment(a, b, projection));
  }
  return { minor: minor.join(""), major: major.join("") };
}

export function radialTicks(cx: number, cy: number, radius: number, count: number, every: number, z: number, lengths: [number, number], projection: Projection, from = 0, span = Math.PI * 2): Ticks {
  const minor: string[] = [];
  const major: string[] = [];
  const closed = Math.abs(span - Math.PI * 2) < 1e-9;
  const steps = closed ? count : count + 1;
  for (let index = 0; index < steps; index++) {
    const angle = from + (index / count) * span;
    const big = index % every === 0;
    const inner = radius - (big ? lengths[1] : lengths[0]);
    const sx = Math.sin(angle);
    const sy = -Math.cos(angle);
    (big ? major : minor).push(lineOnTop([cx + sx * inner, cy + sy * inner], [cx + sx * radius, cy + sy * radius], z, projection));
  }
  return { minor: minor.join(""), major: major.join("") };
}

export const haloOf = (plan: Plan, z: number, height: number, projection: Projection) => slabOf(plan, z, height, projection).fill;

export function axisVector(projection: Projection, [dx, dy, dz]: Point3): Flat {
  const origin = iso([0, 0, 0], projection);
  const moved = iso([dx, dy, dz], projection);
  return [moved[0] - origin[0], moved[1] - origin[1]];
}

const fine = (value: number) => Math.round(value * 100) / 100;

export function translateAlong(projection: Projection, by: Point3) {
  const [x, y] = axisVector(projection, by);
  return `translate(${fine(x)} ${fine(y)})`;
}

const thousandth = (value: number) => Math.round(value * 1000) / 1000;

function axesAt(at: Plane, z: number, projection: Projection) {
  const origin = iso([at[0], at[1], z], projection);
  const along = (point: Point3): Flat => {
    const [px, py] = iso(point, projection);
    return [px - origin[0], py - origin[1]];
  };
  return { origin, x: along([at[0] + 1, at[1], z]), y: along([at[0], at[1] + 1, z]), z: along([at[0], at[1], z + 1]) };
}

const matrixOf = (u: Flat, v: Flat, origin: Flat) =>
  `matrix(${thousandth(u[0])} ${thousandth(u[1])} ${thousandth(v[0])} ${thousandth(v[1])} ${thousandth(origin[0])} ${thousandth(origin[1])})`;

export function holdStill(element: Element, [dx, dy]: Flat) {
  const text = dx || dy ? `translate(${-dx} ${-dy})` : "";
  element.querySelectorAll("[data-hold]").forEach((node) => (text ? node.setAttribute("transform", text) : node.removeAttribute("transform")));
}

export function topMatrix(at: Plane, z: number, projection: Projection, along: "x" | "y" = "x") {
  const { origin, x, y } = axesAt(at, z, projection);
  return along === "x" ? matrixOf(x, y, origin) : matrixOf([-y[0], -y[1]], x, origin);
}

export function sideMatrix(at: Plane, z: number, projection: Projection, face: "left" | "right") {
  const { origin, x, y, z: up } = axesAt(at, z, projection);
  const down: Flat = [-up[0], -up[1]];
  return face === "left" ? matrixOf(x, down, origin) : matrixOf([-y[0], -y[1]], down, origin);
}

export function screenRise(height: number, projection: Projection) {
  const { cosE, k } = cameraOf(projection);
  return height * cosE * k;
}

export interface FitOptions {
  pad?: number;
  headroom?: number;
  azimuth?: number;
  elevation?: number;
}

export function fitProjection(points: Point3[], width: number, height: number, { pad = 24, headroom = 0, azimuth = AZIMUTH, elevation = ELEVATION }: FitOptions = {}): Projection {
  const unit: Projection = { origin: [0, 0], scale: 1, azimuth, elevation };
  const flat = points.map((point) => iso(point, unit));
  const xs = flat.map(([x]) => x);
  const ys = flat.map(([, y]) => y);
  const left = Math.min(...xs);
  const right = Math.max(...xs);
  const up = Math.min(...ys);
  const down = Math.max(...ys);
  const scale = Math.min((width - pad * 2) / (right - left), (height - pad * 2 - headroom) / (down - up));
  return {
    origin: [width / 2 - ((left + right) / 2) * scale, headroom + (height - headroom) / 2 - ((up + down) / 2) * scale],
    scale,
    azimuth,
    elevation,
  };
}

const escape = (text: string) => text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

const attrs = (pairs: Record<string, string | number | undefined | false>) =>
  Object.entries(pairs)
    .filter(([, value]) => value !== undefined && value !== false)
    .map(([key, value]) => ` ${key}="${escape(String(value))}"`)
    .join("");

export interface SolidStyle {
  tone?: Tone;
  crease?: Tone | "none";
  halo?: boolean;
  lit?: boolean;
  flat?: boolean;
  className?: string;
  inner?: string;
}

export function solidSvg(paths: SolidPaths, { tone = "hi", crease = "faint", halo = false, lit = false, flat = false, className, inner = "" }: SolidStyle = {}) {
  const parts: string[] = [];
  if (halo) parts.push(`<path class="iso-halo" d="${paths.fill}"/>`);
  parts.push(`<path class="iso-fill" d="${paths.fill}"/>`);
  if (!flat) {
    paths.shades.forEach((d, shade) => {
      if (d) parts.push(`<path class="iso-shade" data-shade="${shade}" d="${d}"/>`);
    });
    parts.push(`<path class="iso-top" d="${paths.top}"/>`);
  }
  if (crease !== "none" && paths.crease) parts.push(`<path class="iso-line iso-crease" data-tone="${crease}" d="${paths.crease}"/>`);
  if (crease !== "none" && paths.bevel) parts.push(`<path class="iso-line iso-bevel" data-tone="${crease}" d="${paths.bevel}"/>`);
  if (inner) parts.push(inner);
  parts.push(`<path class="iso-line iso-edge" data-tone="${tone}" d="${paths.outline}"/>`);
  return `<g${attrs({ class: className ? `iso-solid ${className}` : "iso-solid", "data-lit": lit ? "" : undefined, "data-seamless": paths.seamless ? "" : undefined })}>${parts.join("")}</g>`;
}

export interface LineStyle {
  tone?: LineTone;
  dotted?: boolean;
  dashed?: boolean;
  flow?: boolean;
  className?: string;
  free?: boolean | "start" | "end";
}

export function lineSvg(d: string, { tone = "lo", dotted = false, dashed = false, flow = false, className, free }: LineStyle = {}) {
  if (!d) return "";
  return `<path${attrs({
    class: className ? `iso-line ${className}` : "iso-line",
    "data-tone": tone,
    "data-free": free === true ? "" : free || undefined,
    "data-dotted": dotted ? "" : undefined,
    "data-dashed": dashed ? "" : undefined,
    "data-flow": flow ? "" : undefined,
    d,
  })}/>`;
}

export function dotsSvg(points: Array<Flat | [number, number, number]>, { size = 0.5, tone = "mid", pulse = false }: { size?: number; tone?: Tone; pulse?: boolean } = {}) {
  const dots = points
    .map(([x, y, alpha]: number[], index) => `<circle cx="${tenth(x)}" cy="${tenth(y)}" r="${size}"${alpha !== undefined && alpha < 1 ? ` fill-opacity="${Math.max(0, alpha).toFixed(2)}"` : ""}${pulse ? ` data-pulse="" style="--pulse-at:${(index * 137) % 1600}ms"` : ""}/>`)
    .join("");
  return `<g class="iso-dots" data-tone="${tone}">${dots}</g>`;
}

export type Faded = { d: string; alpha: number } | [string, number];

export function fadedSvg(list: Faded[], style: LineStyle = {}) {
  const groups = new Map<number, string>();
  for (const entry of list) {
    const [d, alpha] = Array.isArray(entry) ? entry : [entry.d, entry.alpha];
    if (!d || !(alpha > 0.02)) continue;
    const level = Math.min(1, Math.round(alpha * 20) / 20);
    groups.set(level, (groups.get(level) ?? "") + d);
  }
  return [...groups].map(([alpha, d]) => (alpha >= 1 ? lineSvg(d, style) : `<g opacity="${alpha.toFixed(2)}">${lineSvg(d, style)}</g>`)).join("");
}

export interface FadeLineStyle {
  fade?: number | [number, number];
  tone?: LineTone;
  className?: string;
  stops?: number;
}

export function fadeLineSvg(points: Flat[], { fade = [0, 0], tone = "lo", className, stops = 6 }: FadeLineStyle = {}) {
  if (points.length < 2) return "";
  const ease = (t: number) => t * t * (3 - 2 * t);
  const hashOf = (text: string) => {
    let hash = 2166136261;
    for (let index = 0; index < text.length; index++) hash = Math.imul(hash ^ text.charCodeAt(index), 16777619);
    return (hash >>> 0).toString(36);
  };
  const lengths = [0];
  for (let index = 1; index < points.length; index++) lengths.push(lengths[index - 1] + Math.hypot(points[index][0] - points[index - 1][0], points[index][1] - points[index - 1][1]));
  const at = (length: number): Flat => {
    let index = 1;
    while (index < points.length - 1 && lengths[index] < length) index++;
    const span = lengths[index] - lengths[index - 1] || 1;
    const t = Math.max(0, Math.min(1, (length - lengths[index - 1]) / span));
    return [points[index - 1][0] + (points[index][0] - points[index - 1][0]) * t, points[index - 1][1] + (points[index][1] - points[index - 1][1]) * t];
  };
  const pieceOf = (from: number, to: number): Flat[] => [at(from), ...points.filter((_, index) => lengths[index] > from + 1e-6 && lengths[index] < to - 1e-6), at(to)];
  const total = lengths[lengths.length - 1];
  if (total < 1e-6) return "";
  let [start, end] = Array.isArray(fade) ? fade : [fade, fade];
  if (start + end > total) {
    const share = total / (start + end);
    start *= share;
    end *= share;
  }
  const paint = `var(--anatomy-${tone})`;
  const ramp = (piece: Flat[], rising: boolean) => {
    const d = pathOf(piece);
    const [x1, y1] = piece[0];
    const [x2, y2] = piece[piece.length - 1];
    const id = `iso-fade-${hashOf(`${d}|${tone}|${rising}`)}`;
    const marks = Array.from({ length: stops + 1 }, (_, index) => {
      const t = index / stops;
      const alpha = ease(rising ? t : 1 - t);
      return `<stop offset="${t.toFixed(3)}" stop-opacity="${alpha.toFixed(3)}" style="stop-color:${paint}"/>`;
    }).join("");
    const gradient = `<linearGradient id="${id}" gradientUnits="userSpaceOnUse" x1="${tenth(x1)}" y1="${tenth(y1)}" x2="${tenth(x2)}" y2="${tenth(y2)}">${marks}</linearGradient>`;
    return `<defs>${gradient}</defs><path${attrs({ class: className ? `iso-line ${className}` : "iso-line", "data-tone": tone, "data-free": rising ? "start" : "end", d, style: `stroke:url(#${id})` })}/>`;
  };
  const parts: string[] = [];
  if (start > 0.05) parts.push(ramp(pieceOf(0, start), true));
  if (total - end - start > 0.05) parts.push(lineSvg(pathOf(pieceOf(start, total - end)), { tone, className }));
  if (end > 0.05) parts.push(ramp(pieceOf(total - end, total), false));
  return `<g class="iso-fade">${parts.join("")}</g>`;
}

export interface WireStyle {
  via?: Flat[];
  tone?: LineTone;
  dotted?: boolean;
  dashed?: boolean;
  flow?: boolean;
  ends?: "both" | "from" | "to" | "none";
  size?: number;
}

export function wireSvg(from: Flat, to: Flat, { via = [], tone = "lo", dotted = false, dashed = false, flow = false, ends = "both", size = 1.2 }: WireStyle = {}) {
  const d = pathOf([from, ...via, to]);
  const end = ([x, y]: Flat) => `<circle class="iso-wire-end" cx="${tenth(x)}" cy="${tenth(y)}" r="${size}"/>`;
  return `<g class="iso-wire" data-tone="${tone}">${lineSvg(d, { tone, dotted, dashed, flow })}${ends === "both" || ends === "from" ? end(from) : ""}${ends === "both" || ends === "to" ? end(to) : ""}</g>`;
}

export function faceTextSvg(transform: string, text: string, { size = 3, tone = "mid", anchor = "start" }: { size?: number; tone?: Tone; anchor?: "start" | "middle" | "end" } = {}) {
  return `<text class="iso-face-text" data-tone="${tone}" transform="${transform}" font-size="${size}" text-anchor="${anchor}">${escape(text)}</text>`;
}

export function groupSvg(children: string | string[], extra: Record<string, string | number | undefined | false> = {}) {
  return `<g${attrs(extra)}>${Array.isArray(children) ? children.join("") : children}</g>`;
}

export type Theme = "dark" | "light";

export interface FigureOptions {
  width: number;
  height: number;
  label: string;
  body: string | string[];
  standalone?: Theme | false;
  className?: string;
}

export function figureSvg({ width, height, label, body, standalone = false, className }: FigureOptions) {
  const style = standalone ? `<style>${ISO_CSS}</style>` : "";
  return `<svg${attrs({
    xmlns: "http://www.w3.org/2000/svg",
    class: `iso-svg${standalone ? " iso" : ""}${className ? ` ${className}` : ""}`,
    "data-theme": standalone || undefined,
    viewBox: `0 0 ${width} ${height}`,
    role: "img",
    "aria-label": label,
  })}>${style}${Array.isArray(body) ? body.join("") : body}</svg>`;
}

export type KeyMark = "raised" | "flat" | "lit" | "edge" | "dim" | "dotted" | "dashed" | "red" | "green" | "blue";

export interface LegendKey {
  mark: KeyMark;
  label: string;
}

function swatchSvg(mark: KeyMark) {
  if (mark === "raised" || mark === "flat" || mark === "lit") {
    const body = mark === "flat" ? "M2 6.5 8 3.5 14 6.5 8 9.5Z" : "M2 4.5 8 1.5 14 4.5 14 6 8 9 2 6Z";
    const crease = mark === "flat" ? "" : `<path class="iso-swatch-crease" d="M2 4.5 8 7.5 14 4.5"/>`;
    return `<svg class="iso-swatch" data-mark="${mark}" viewBox="0 0 16 10" aria-hidden="true"><path d="${body}"/>${crease}</svg>`;
  }
  return `<svg class="iso-swatch" data-mark="${mark}" viewBox="0 0 16 10" aria-hidden="true"><path d="M1.5 5h13"/></svg>`;
}

export interface PlateOptions {
  fig: string;
  title?: string;
  hint?: string;
  readout?: string;
  keys?: LegendKey[];
  caption?: string;
  body: string;
}

export function plateHtml({ fig, title, hint, readout = "", keys = [], caption, body }: PlateOptions) {
  const corner = (name: string, text: string, extra = "") => `<span class="iso-plate-corner" data-corner="${name}"${extra}>${escape(text)}</span>`;
  const legend =
    keys.length || caption
      ? `<figcaption class="iso-legend">${keys.length ? `<span class="iso-keys">${keys.map((key) => `<span class="iso-key">${swatchSvg(key.mark)}${escape(key.label)}</span>`).join("")}</span>` : ""}${caption ? `<span class="iso-caption">${escape(caption)}</span>` : ""}</figcaption>`
      : "";
  return `<figure class="iso-figure"><div class="iso-plate"><div class="iso-plate-corners" aria-hidden="true">${corner("fig", fig)}${title ? corner("title", title) : ""}${hint ? corner("hint", hint) : ""}${corner("readout", readout, " data-readout")}</div>${body}</div>${legend}</figure>`;
}

export interface PageOptions {
  title: string;
  theme?: Theme;
  body: string;
  script?: string;
  width?: number;
}

export function pageHtml({ title, theme = "dark", body, script = "", width = 650 }: PageOptions) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${escape(title)}</title><style>${ISO_CSS}${PAGE_CSS.replace("__WIDTH__", String(width))}</style></head><body class="iso" data-theme="${theme}"><main class="iso-page">${body}</main>${script ? `<script type="module">${script.replace(/<\/(script)/gi, "<\\/$1")}</script>` : ""}</body></html>`;
}

